def get_size_range_index(basic_size: float) -> int:
    """根据基本尺寸查找对应的尺寸段索引"""
    for i, (low, high) in enumerate(SIZE_RANGES):
        if basic_size == 0 and low == 0:
            if basic_size <= high:
                return i
        elif low < basic_size <= high:
            return i
    return -1


def get_deviations(fit_code: str, basic_size: float):
    """
    查询极限偏差
    
    Args:
        fit_code: 配合代号, 如 "H7", "g6", "k7" 等
        basic_size: 基本尺寸 (mm)
    
    Returns:
        (上偏差, 下偏差) 单位μm, 或 None
    """
    size_idx = get_size_range_index(basic_size)
    if size_idx == -1:
        return None
    
    code = fit_code.strip()
    
    # 查孔偏差
    if code in HOLE_DEVIATIONS:
        data = HOLE_DEVIATIONS[code]
        if size_idx < len(data):
            return data[size_idx]
        return None  # 超出该代号数据行长度(如>500mm非基准段)无数据
    
    # 查轴偏差
    if code in SHAFT_DEVIATIONS:
        data = SHAFT_DEVIATIONS[code]
        if size_idx < len(data):
            return data[size_idx]
        return None  # 超出该代号数据行长度(如>500mm非基准段)无数据
    
    return None


def fit_type_from_devs(hole_dev, shaft_dev) -> str:
    """按上下偏差数值判断配合类型（代号查询与自定义偏差共用同一判定）。

    Args:
        hole_dev: (上偏差 es, 下偏差 ei) 单位 μm
        shaft_dev: (上偏差 es, 下偏差 ei) 单位 μm
    """
    h_es, h_ei = hole_dev
    s_es, s_ei = shaft_dev
    max_gap = h_es - s_ei    # 最大间隙
    min_gap = h_ei - s_es    # 负值=最大过盈
    if min_gap >= 0:
        return "间隙配合"
    elif max_gap <= 0:
        return "过盈配合"
    else:
        return "过渡配合"


def get_fit_type(hole_code: str, shaft_code: str, basic_size: float = None) -> str:
    """判断配合类型。
    如果提供 basic_size，根据实际偏差数值判断（更准确）；
    否则按代号字母判断（兜底）。
    """
    if basic_size is not None:
        hole_dev = get_deviations(hole_code, basic_size)
        shaft_dev = get_deviations(shaft_code, basic_size)
        if hole_dev and shaft_dev:
            return fit_type_from_devs(hole_dev, shaft_dev)

    # 兜底：按代号字母判断
    hole_letter = ''.join(c for c in hole_code if c.isalpha()).upper()
    shaft_letter = ''.join(c for c in shaft_code if c.isalpha()).lower()

    if hole_letter == "H":
        if shaft_letter in ("a", "b", "c", "d", "e", "f", "g"):
            return "间隙配合"
        elif shaft_letter in ("h", "js", "j", "k", "m", "n"):
            return "过渡配合"
        else:
            return "过盈配合"

    if shaft_letter == "h":
        if hole_letter in ("A", "B", "C", "D", "E", "F", "G"):
            return "间隙配合"
        elif hole_letter in ("H", "JS", "J", "K", "M", "N"):
            return "过渡配合"
        else:
            return "过盈配合"

    return "未知配合"


